import torch
import triton
import triton.language as tl
from triton.runtime import driver


def _dtype_code(dt):
    if dt == torch.float32:
        return 0
    if dt == torch.float16:
        return 1
    if dt == torch.bfloat16:
        return 2
    if dt == torch.int32:
        return 3
    if dt == torch.int64:
        return 4
    if dt == torch.int16:
        return 5
    if dt == torch.int8:
        return 6
    if dt == torch.uint8:
        return 7
    if dt == torch.bool:
        return 8
    return 0


@triton.jit
def _cast_compute(x, COMPUTE_CODE: tl.constexpr):
    if COMPUTE_CODE == 0:
        return x.to(tl.float32)
    elif COMPUTE_CODE == 1:
        return x.to(tl.float16)
    elif COMPUTE_CODE == 2:
        return x.to(tl.bfloat16)
    elif COMPUTE_CODE == 3:
        return x.to(tl.int32)
    elif COMPUTE_CODE == 4:
        return x.to(tl.int64)
    elif COMPUTE_CODE == 5:
        return x.to(tl.int16)
    elif COMPUTE_CODE == 6:
        return x.to(tl.int8)
    elif COMPUTE_CODE == 7:
        return x.to(tl.uint8)
    else:
        return x.to(tl.int8)


# Persistent kernel. A fixed, smaller-than-work grid (each program iterating
# multiple blocks) avoids a flagtree codegen defect under
# TRITON_ALL_BLOCKS_PARALLEL=1 that corrupts the single standalone pid==0 block
# when the grid equals the block count. Each program processes a CONTIGUOUS run
# of blocks (block-cyclic) rather than a strided set, which improves per-program
# HBM locality/prefetch. SAME_DTYPE skips the operand up-cast on the common
# equal-dtype path (bit-exact and cheaper).
@triton.jit
def _ge_linear_kernel(
    A_ptr,
    B_ptr,
    N,
    n_blocks,
    blocks_per,
    COMPUTE_CODE: tl.constexpr,
    SAME_DTYPE: tl.constexpr,
    B_SCALAR: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    start = pid * blocks_per
    end = start + blocks_per
    if B_SCALAR:
        bs = tl.load(B_ptr)
    for blk in range(start, end):
        if blk < n_blocks:
            offs = blk * BLOCK + tl.arange(0, BLOCK)
            mask = offs < N
            a = tl.load(A_ptr + offs, mask=mask)
            if B_SCALAR:
                b = bs
            else:
                b = tl.load(B_ptr + offs, mask=mask)
            if SAME_DTYPE:
                res = a >= b
            else:
                res = _cast_compute(a, COMPUTE_CODE) >= _cast_compute(b, COMPUTE_CODE)
            tl.store(A_ptr + offs, res.to(a.dtype), mask=mask)


@triton.jit
def _ge_strided_kernel(
    A_ptr,
    B_ptr,
    N,
    n_blocks,
    blocks_per,
    sh0,
    sh1,
    sh2,
    sh3,
    sh4,
    sh5,
    sh6,
    sh7,
    as0,
    as1,
    as2,
    as3,
    as4,
    as5,
    as6,
    as7,
    bs0,
    bs1,
    bs2,
    bs3,
    bs4,
    bs5,
    bs6,
    bs7,
    NDIM: tl.constexpr,
    COMPUTE_CODE: tl.constexpr,
    SAME_DTYPE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    start = pid * blocks_per
    end = start + blocks_per
    for blk in range(start, end):
        if blk < n_blocks:
            lin = blk * BLOCK + tl.arange(0, BLOCK)
            mask = lin < N
            rem = lin
            a_off = tl.zeros_like(lin)
            b_off = tl.zeros_like(lin)
            for d in tl.static_range(NDIM - 1, -1, -1):
                if d == 0:
                    s = sh0
                    ast = as0
                    bst = bs0
                elif d == 1:
                    s = sh1
                    ast = as1
                    bst = bs1
                elif d == 2:
                    s = sh2
                    ast = as2
                    bst = bs2
                elif d == 3:
                    s = sh3
                    ast = as3
                    bst = bs3
                elif d == 4:
                    s = sh4
                    ast = as4
                    bst = bs4
                elif d == 5:
                    s = sh5
                    ast = as5
                    bst = bs5
                elif d == 6:
                    s = sh6
                    ast = as6
                    bst = bs6
                else:
                    s = sh7
                    ast = as7
                    bst = bs7
                c = rem % s
                rem = rem // s
                a_off += c * ast
                b_off += c * bst
            a = tl.load(A_ptr + a_off, mask=mask)
            b = tl.load(B_ptr + b_off, mask=mask)
            if SAME_DTYPE:
                res = a >= b
            else:
                res = _cast_compute(a, COMPUTE_CODE) >= _cast_compute(b, COMPUTE_CODE)
            tl.store(A_ptr + a_off, res.to(a.dtype), mask=mask)


_NUM_VC = None


def _num_vectorcore():
    global _NUM_VC
    if _NUM_VC is None:
        try:
            props = driver.active.utils.get_device_properties(
                torch.npu.current_device()
            )
            _NUM_VC = int(props["num_vectorcore"])
        except Exception:
            _NUM_VC = 40
    return _NUM_VC


def greater_equal_(A, B):
    N = A.numel()
    if N == 0:
        return A

    code = _dtype_code(torch.promote_types(A.dtype, B.dtype))
    same_dtype = A.dtype == B.dtype
    nvc = _num_vectorcore()
    # Larger tiles maximize streaming bandwidth on this memory-bound op. The
    # tile is capped by the Ascend bishengir unified-buffer limit. 2-byte dtypes
    # (fp16, and bf16 on the SAME_DTYPE path that compares directly without an
    # fp32 temp) fit 16384; 4-byte fp32, and the mixed-dtype bf16 path that
    # needs an fp32 temp, must stay at 8192.
    two_byte_direct = A.dtype == torch.float16 or (
        A.dtype == torch.bfloat16 and same_dtype
    )
    big_block = 16384 if two_byte_direct else 8192
    # For inputs too small to fill one big tile per core, shrink BLOCK so the
    # work spreads across all vector cores instead of leaving most idle; large
    # inputs keep the big tile (at the HBM bandwidth ceiling).
    if N <= big_block * nvc:
        per = (N + nvc - 1) // nvc
        per_pow2 = 1 << max(0, (per - 1)).bit_length()
        BLOCK = min(big_block, max(256, per_pow2))
    else:
        BLOCK = big_block
    n_blocks = triton.cdiv(N, BLOCK)
    # Persistent launch capped at num_vectorcore (and by work). For large
    # tensors this keeps the launch count below n_blocks, which also avoids a
    # flagtree codegen defect that corrupts a lone standalone pid==0 block under
    # TRITON_ALL_BLOCKS_PARALLEL. Each program handles a contiguous run of
    # blocks_per blocks (block-cyclic) for better per-program HBM locality.
    n_prog = min(nvc, n_blocks)
    grid = (n_prog,)
    blocks_per = (n_blocks + n_prog - 1) // n_prog

    b_scalar = B.numel() == 1
    fast = A.is_contiguous() and (
        b_scalar or (B.is_contiguous() and tuple(B.shape) == tuple(A.shape))
    )

    if fast:
        _ge_linear_kernel[grid](
            A,
            B,
            N,
            n_blocks,
            blocks_per,
            COMPUTE_CODE=code,
            SAME_DTYPE=same_dtype,
            B_SCALAR=b_scalar,
            BLOCK=BLOCK,
        )
        return A

    shape = list(A.shape) if A.dim() > 0 else [1]
    a_strides = list(A.stride()) if A.dim() > 0 else [0]
    B_exp = B.expand(shape)
    b_strides = list(B_exp.stride())
    ndim = len(shape)
    assert ndim <= 8, "general path supports up to 8 dims"

    sh = shape + [1] * (8 - ndim)
    ast = a_strides + [0] * (8 - ndim)
    bst = b_strides + [0] * (8 - ndim)

    _ge_strided_kernel[grid](
        A,
        B,
        N,
        n_blocks,
        blocks_per,
        sh[0],
        sh[1],
        sh[2],
        sh[3],
        sh[4],
        sh[5],
        sh[6],
        sh[7],
        ast[0],
        ast[1],
        ast[2],
        ast[3],
        ast[4],
        ast[5],
        ast[6],
        ast[7],
        bst[0],
        bst[1],
        bst[2],
        bst[3],
        bst[4],
        bst[5],
        bst[6],
        bst[7],
        NDIM=ndim,
        COMPUTE_CODE=code,
        SAME_DTYPE=same_dtype,
        BLOCK=BLOCK,
    )
    return A
